### Recommendations

Rather than loading secrets from `.env` files (which get accidentally committed, lack rotation, and have no access auditing), I'd recommend integrating a proper secrets manager. Here's a pattern for the future:

```js
// secrets.js — abstraction layer for secrets access
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
// Or for AWS:
// const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  if (process.env.NODE_ENV === 'development') {
    // Only allow .env fallback in local dev, never production
    return process.env[secretName];
  }

  const client = new SecretManagerServiceClient();
  const [version] = await client.accessSecretVersion({
    name: `projects/my-project/secrets/${secretName}/versions/latest`,
  });
  return version.payload.data.toString('utf8');
}

module.exports = { getSecret };
```

```js
// Usage in app.js
const { getSecret } = require('./secrets');

async function startApp() {
  const dbUrl = await getSecret('DATABASE_URL');
  const stripeKey = await getSecret('STRIPE_SECRET_KEY');
  // ... initialize services with retrieved secrets
}
```

