### Don't Use `.env` Files for Production Secrets

`.env` files are acceptable for local development only. For production, use a dedicated secrets manager:

```javascript
// ❌ BAD: Loading secrets from filesystem
require('dotenv').config();
const dbPassword = process.env.DATABASE_URL;

// ✅ GOOD: Fetch from a secrets manager at startup
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
// or AWS Secrets Manager, HashiCorp Vault, etc.

async function loadSecrets() {
  const client = new SecretManagerServiceClient();
  const [version] = await client.accessSecretVersion({
    name: 'projects/my-project/secrets/DATABASE_URL/versions/latest',
  });
  return version.payload.data.toString('utf8');
}
```

### AWS Secrets Manager Example

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: secretName })
  );
  return JSON.parse(response.SecretString);
}

// Usage at app startup
async function bootstrap() {
  const secrets = await getSecret('my-app/production');
  // secrets.DATABASE_URL, secrets.STRIPE_SECRET_KEY, etc.
}
```

### HashiCorp Vault Example

```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN, // Only the Vault token in env
});

async function loadSecrets() {
  const { data } = await vault.read('secret/data/my-app');
  return data.data; // { DATABASE_URL: '...', STRIPE_SECRET_KEY: '...' }
}
```

