app.use(helmet());
```

---

### 3. No Rate Limiting

**Issue:** Without rate limiting, the app is vulnerable to brute-force attacks, denial-of-service, and scraping. This relates to **OWASP A04:2021 – Insecure Design**.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});

app.use(limiter);
```

